for (let i = 1; i <= 6; i++) {
  const { page } = await newRetailPage(browser, "d" + i, { viewport: { width: 1440, height: 900 } });
  await page.route("**/api/property/**", (r) => json(r, []));
  await page.route("**/api/trades/**", (r) => json(r, []));
  await page.goto(`${BASE_URL}/dashboard`, { waitUntil: "networkidle" });
  await page.waitForTimeout(1500);
  const n = await page.locator('[data-testid="desktop-frame"]').count();
  const dbg = await page.evaluate(() => ({
    loads: window.__chromeModuleLoads,
    uniq: new Set(window.__chromeCtxIds || []).size,
  }));
  console.log(`run ${i}: frames=${n} moduleLoads=${dbg.loads} uniqueContexts=${dbg.uniq}`);
  await page.context().close();
}
await browser.close();
